/*
 * Hand-written MCP Events helpers. Not generated by Speakeasy: this file is not
 * tracked in .speakeasy/gen.lock, so it survives SDK regeneration.
 */

import {
  asMcpErrorObject,
  isPlainObject,
  MCPError,
  McpEventsRequestError,
} from "./errors.js";

/** An MCP result object, forwarded verbatim from Outpost. */
export type McpResult = Record<string, unknown>;

export type ListEventsQuery = {
  /** The `cursor` from the MCP `events/list` request. */
  cursor?: string | undefined;
  /**
   * The topics the principal may discover. `undefined` means no filter; an
   * empty array means no topics (Outpost answers with no events).
   */
  topics?: readonly string[] | undefined;
  /** Page size, 1 to 100. Outpost defaults to 100. */
  limit?: number | undefined;
};

export type SubscribeBody = {
  /** The authenticated subject of the MCP request. */
  principal: string;
  /** The MCP `events/subscribe` params, untouched. */
  params: Record<string, unknown>;
  /** Replaces the filter Outpost generates from `params.arguments`. */
  filter?: Record<string, unknown> | undefined;
  /** Copied to the subscription's destination. */
  metadata?: Record<string, string> | undefined;
  /** Outpost answers not_found for a `params.name` outside this list. */
  allowed_topics?: readonly string[] | undefined;
};

export type UnsubscribeBody = {
  principal: string;
  /** The MCP `events/unsubscribe` params, untouched. */
  params: Record<string, unknown>;
};

export type McpCallOptions = {
  /** Aborts the Outpost call, for example when the MCP request is cancelled. */
  signal?: AbortSignal | undefined;
};

/**
 * The three Outpost endpoints the MCP Events handlers proxy. Results are the
 * MCP results, ready to return verbatim. MCP failures reject with MCPError.
 */
export interface McpEventsApi {
  listEvents(
    tenantId: string,
    query?: ListEventsQuery,
    options?: McpCallOptions,
  ): Promise<McpResult>;
  subscribe(
    tenantId: string,
    body: SubscribeBody,
    options?: McpCallOptions,
  ): Promise<McpResult>;
  unsubscribe(
    tenantId: string,
    body: UnsubscribeBody,
    options?: McpCallOptions,
  ): Promise<McpResult>;
}

/** The subset of HTTPClient (src/lib/http.ts) the client uses. */
export type McpEventsHTTPClient = {
  request(request: Request): Promise<Response>;
};

export type McpEventsClientConfig = {
  /**
   * The Outpost API base URL, for example `http://localhost:3333/api/v2`. The
   * MCP endpoints exist in API v2 only, so a URL ending in `/api/v1` is
   * rewritten to `/api/v2`.
   */
  serverURL: string | URL;
  /** The Outpost API key (admin key on self-hosted Outpost). */
  apiKey?: string | (() => Promise<string>) | undefined;
  /** Sends the requests. Defaults to the global fetch. */
  httpClient?: McpEventsHTTPClient | undefined;
  /**
   * Per-call timeout in milliseconds. Defaults to 30s, above Outpost's own
   * 20s subscribe deadline (subscribe verifies the callback synchronously).
   */
  timeoutMs?: number | undefined;
  /** Largest response body accepted, in bytes. Defaults to 8 MiB. */
  maxResponseBytes?: number | undefined;
};

/**
 * The parts of an `Outpost` (or `OutpostCore`) instance the client reads:
 * the resolved base URL and the options it was built with. Typed
 * structurally so this module does not import the generated SDK class.
 */
export type OutpostLike = {
  readonly _baseURL?: URL | null | undefined;
  readonly _options: {
    readonly apiKey?: string | (() => Promise<string>) | undefined;
    readonly serverURL?: string | undefined;
    readonly httpClient?: McpEventsHTTPClient | undefined;
    readonly timeoutMs?: number | undefined;
  };
};

/** What the helpers accept as their Outpost connection. */
export type McpEventsSource = OutpostLike | McpEventsClientConfig | McpEventsApi;

export const DEFAULT_TIMEOUT_MS = 30_000;
export const DEFAULT_MAX_RESPONSE_BYTES = 8 * 1024 * 1024;
const MAX_ERROR_BODY_CHARS = 1024;

/**
 * A raw-JSON client for the Outpost MCP endpoints. It never reshapes request
 * params or results, so fields the protocol adds later pass through.
 */
export class McpEventsClient implements McpEventsApi {
  readonly #baseURL: URL;
  readonly #apiKey: string | (() => Promise<string>) | undefined;
  readonly #httpClient: McpEventsHTTPClient | undefined;
  readonly #timeoutMs: number;
  readonly #maxResponseBytes: number;

  constructor(config: McpEventsClientConfig) {
    this.#baseURL = normalizeBaseURL(config.serverURL);
    this.#apiKey = config.apiKey;
    this.#httpClient = config.httpClient;
    this.#timeoutMs = positiveOr(config.timeoutMs, DEFAULT_TIMEOUT_MS);
    this.#maxResponseBytes = positiveOr(
      config.maxResponseBytes,
      DEFAULT_MAX_RESPONSE_BYTES,
    );
  }

  /** The base URL the endpoints are resolved against (always API v2). */
  get baseURL(): string {
    return this.#baseURL.href;
  }

  /** GET /tenants/{tenant_id}/mcp/events, the `events/list` result. */
  async listEvents(
    tenantId: string,
    query: ListEventsQuery = {},
    options: McpCallOptions = {},
  ): Promise<McpResult> {
    const url = this.#url(tenantId, "mcp/events");
    if (query.cursor !== undefined) {
      url.searchParams.set("cursor", query.cursor);
    }
    if (query.topics !== undefined) {
      // Present but empty means "no topics" to Outpost, so an empty
      // allowlist never widens to the whole catalog.
      url.searchParams.set("topics", query.topics.join(","));
    }
    if (query.limit !== undefined) {
      url.searchParams.set("limit", String(query.limit));
    }
    return this.#call("GET", url, undefined, options);
  }

  /** PUT /tenants/{tenant_id}/mcp/subscriptions, the `events/subscribe` result. */
  async subscribe(
    tenantId: string,
    body: SubscribeBody,
    options: McpCallOptions = {},
  ): Promise<McpResult> {
    const url = this.#url(tenantId, "mcp/subscriptions");
    return this.#call("PUT", url, body, options);
  }

  /** POST /tenants/{tenant_id}/mcp/subscriptions/unsubscribe, always `{}`. */
  async unsubscribe(
    tenantId: string,
    body: UnsubscribeBody,
    options: McpCallOptions = {},
  ): Promise<McpResult> {
    const url = this.#url(tenantId, "mcp/subscriptions/unsubscribe");
    return this.#call("POST", url, body, options);
  }

  #url(tenantId: string, path: string): URL {
    return new URL(`tenants/${encodeTenantID(tenantId)}/${path}`, this.#baseURL);
  }

  async #call(
    method: string,
    url: URL,
    body: unknown,
    options: McpCallOptions,
  ): Promise<McpResult> {
    // identity: the size cap then applies to what is actually buffered (a
    // forbidden header in browsers, where it is ignored).
    const headers = new Headers({
      Accept: "application/json",
      "Accept-Encoding": "identity",
    });
    const apiKey = typeof this.#apiKey === "function"
      ? await this.#apiKey()
      : this.#apiKey;
    if (apiKey) {
      headers.set(
        "Authorization",
        apiKey.slice(0, 7).toLowerCase() === "bearer " ? apiKey : `Bearer ${apiKey}`,
      );
    }
    let payload: string | undefined;
    if (body !== undefined) {
      headers.set("Content-Type", "application/json");
      payload = JSON.stringify(body);
    }

    const controller = new AbortController();
    const timer = setTimeout(
      () => controller.abort(new McpEventsRequestError("Outpost request timed out")),
      this.#timeoutMs,
    );
    const outer = options.signal;
    const onAbort = () => controller.abort(outer?.reason);
    if (outer?.aborted) {
      controller.abort(outer.reason);
    } else {
      outer?.addEventListener("abort", onAbort, { once: true });
    }

    try {
      const init: RequestInit = {
        method,
        headers,
        signal: controller.signal,
        // Outpost never redirects; following one would replay the API key.
        redirect: "error",
      };
      if (payload !== undefined) {
        init.body = payload;
      }
      let response: Response;
      let text: string;
      try {
        // Some runtimes (Bun 1.2) drop `redirect` from a Request object, so
        // the global fetch gets the init directly.
        response = this.#httpClient
          ? await this.#httpClient.request(new Request(url, init))
          : await fetch(url, init);
        if (response.redirected) {
          await response.body?.cancel().catch(() => {});
          throw new McpEventsRequestError("Outpost redirected the request", {
            statusCode: response.status,
          });
        }
        text = await readBody(response, this.#maxResponseBytes);
      } catch (err) {
        if (err instanceof McpEventsRequestError) {
          throw err;
        }
        throw new McpEventsRequestError("Outpost request failed", { cause: err });
      }
      return parseResponse(response.status, text);
    } finally {
      clearTimeout(timer);
      outer?.removeEventListener("abort", onAbort);
    }
  }
}

/**
 * Builds the client for any accepted source: an `Outpost` instance (its
 * resolved server URL, API key, HTTP client and timeout), an explicit
 * `{ serverURL, apiKey }` config, or any object already implementing the
 * three calls.
 */
export function createMcpEventsClient(source: McpEventsSource): McpEventsApi {
  if (isMcpEventsApi(source)) {
    return source;
  }
  if (isOutpostLike(source)) {
    const options = source._options;
    const serverURL = source._baseURL ?? options.serverURL;
    if (!serverURL) {
      throw new TypeError("The Outpost instance has no server URL");
    }
    return new McpEventsClient({
      serverURL,
      apiKey: options.apiKey,
      httpClient: options.httpClient,
      timeoutMs: options.timeoutMs,
    });
  }
  if (isPlainObject(source) && "serverURL" in source) {
    return new McpEventsClient(source);
  }
  throw new TypeError(
    "Expected an Outpost instance, a { serverURL, apiKey } config or an MCP Events client",
  );
}

function isMcpEventsApi(value: unknown): value is McpEventsApi {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const v = value as Record<string, unknown>;
  return typeof v["listEvents"] === "function"
    && typeof v["subscribe"] === "function"
    && typeof v["unsubscribe"] === "function";
}

function isOutpostLike(value: unknown): value is OutpostLike {
  return typeof value === "object"
    && value !== null
    && isPlainObject((value as Record<string, unknown>)["_options"]);
}

function normalizeBaseURL(serverURL: string | URL): URL {
  const url = new URL(serverURL);
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    throw new TypeError("The Outpost server URL must be http or https");
  }
  let path = url.pathname.replace(/\/+$/, "");
  if (path.endsWith("/api/v1")) {
    path = `${path.slice(0, -"/api/v1".length)}/api/v2`;
  }
  url.pathname = `${path}/`;
  // The API key is the only credential; fetch rejects URLs with userinfo.
  url.username = "";
  url.password = "";
  url.search = "";
  url.hash = "";
  return url;
}

/**
 * Percent-encodes a tenant ID as one path segment. "." and ".." are rejected:
 * URL parsing would resolve them as dot segments and move the request to
 * another path.
 */
export function encodeTenantID(tenantId: string): string {
  if (typeof tenantId !== "string" || tenantId === "" || tenantId === "." || tenantId === "..") {
    throw new TypeError("Invalid tenant ID");
  }
  return encodeURIComponent(tenantId);
}

async function readBody(response: Response, maxBytes: number): Promise<string> {
  const declared = Number(response.headers.get("content-length"));
  if (Number.isFinite(declared) && declared > maxBytes) {
    await response.body?.cancel().catch(() => {});
    throw new McpEventsRequestError("Outpost response is too large", {
      statusCode: response.status,
    });
  }
  if (!response.body) {
    return "";
  }
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    total += value.byteLength;
    if (total > maxBytes) {
      await reader.cancel().catch(() => {});
      throw new McpEventsRequestError("Outpost response is too large", {
        statusCode: response.status,
      });
    }
    chunks.push(value);
  }
  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return new TextDecoder().decode(bytes);
}

function parseResponse(status: number, text: string): McpResult {
  let parsed: unknown;
  let parseError: unknown;
  try {
    parsed = text === "" ? undefined : JSON.parse(text);
  } catch (err) {
    parseError = err;
  }

  if (status >= 200 && status < 300) {
    if (isPlainObject(parsed)) {
      return parsed;
    }
    throw new McpEventsRequestError("Outpost returned a malformed MCP result", {
      statusCode: status,
      body: text.slice(0, MAX_ERROR_BODY_CHARS),
      cause: parseError,
    });
  }

  if (status === 422 && isPlainObject(parsed)) {
    const mcpError = asMcpErrorObject(parsed["mcp_error"]);
    if (mcpError) {
      throw new MCPError(mcpError, status);
    }
  }
  throw new McpEventsRequestError(`Outpost responded with status ${status}`, {
    statusCode: status,
    body: text.slice(0, MAX_ERROR_BODY_CHARS),
  });
}

function positiveOr(value: number | undefined, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? value
    : fallback;
}
